/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.infrastructure.driven;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.consent.domain.GdprConsentPurposeItem;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The decisions on the consent purposes (GDPR art. 7) stored with the repositories on h2. */
class GdprConsentAdapterUnitTest {
  private OidcRepositories store;
  private GdprConsentAdapter consents;
  private String alice;
  private String marketing;
  private String analytics;
  private String foreign;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    String tenant = store.tenant("acme");
    String other = store.tenant("globex");
    alice = store.user(tenant, "alice", "alice@acme.test");
    store.user(other, "alice", "alice@globex.test");
    analytics = purpose(tenant, "ANALYTICS", -1, true);
    marketing = purpose(tenant, "MARKETING", -2, false);
    purpose(tenant, "THIRD_PARTY", 2, false);
    foreign = purpose(other, "PERSONALIZATION", -1, false);
    consents = new GdprConsentAdapter(store.tenants(), store.users(), store.purposes(),
        store.purposeConsents(), store.purposeConsentWriter());
  }

  /** A purpose active since (or from) the given days from now; returns its uid. */
  private String purpose(String tenant, String key, int days, boolean required) {
    String uid = OidcRepositories.uid();
    store.db()
        .execute("INSERT INTO identity_consent_purpose (uid, version, activation_date,"
            + " `description`, `key`, required, title, tenant) VALUES ('" + uid + "', 1,"
            + " DATEADD('DAY', " + days + ", CURRENT_TIMESTAMP), 'About " + key + "', '" + key
            + "', " + required + ", 'Title " + key + "', '" + tenant + "')");
    return uid;
  }

  private List<String> pending() {
    return consents.pendingPurposes("acme", "alice").stream().map(GdprConsentPurposeItem::uid)
        .toList();
  }

  private String decision(String purpose, String column) {
    return store.value("SELECT " + column + " FROM identity_user_purpose_consent WHERE `user` = '"
        + alice + "' AND consent_purpose = '" + purpose + "'");
  }

  @Test
  @DisplayName("The active purposes of the tenant are pending, the oldest first")
  void pending_purposes() {
    List<GdprConsentPurposeItem> items = consents.pendingPurposes("acme", "alice");

    Assertions.assertEquals(List.of(marketing, analytics),
        items.stream().map(GdprConsentPurposeItem::uid).toList(),
        "Neither the future purposes nor those of other tenants are asked");
    Assertions.assertEquals(new GdprConsentPurposeItem(marketing, "MARKETING", "Title MARKETING",
        "About MARKETING", false), items.get(0));
    Assertions.assertTrue(items.get(1).required());
  }

  @Test
  @DisplayName("The decisions are stored once, granted or denied, with where they were taken")
  void store_decisions() {
    Map<String, Boolean> decisions = new LinkedHashMap<>();
    decisions.put(marketing, true);
    decisions.put(analytics, false);
    decisions.put("missing", true);
    decisions.put(foreign, true);

    consents.storePurposeDecisions("acme", "alice", decisions, "10.0.0.1", "Firefox");

    Assertions.assertEquals(2, store.db().count("identity_user_purpose_consent", null),
        "Unknown purposes and those of other tenants are skipped");
    Assertions.assertEquals("TRUE", decision(marketing, "granted").toUpperCase());
    Assertions.assertEquals("FALSE", decision(analytics, "granted").toUpperCase());
    Assertions.assertEquals("10.0.0.1", decision(marketing, "ip_address"));
    Assertions.assertEquals("Firefox", decision(marketing, "user_agent"));
    Assertions.assertNotNull(decision(marketing, "decision_at"));
    Assertions.assertEquals(List.of(), pending(), "A decided purpose is not asked again");

    consents.storePurposeDecisions("acme", "alice", Map.of(marketing, false), null, null);
    Assertions.assertEquals(2, store.db().count("identity_user_purpose_consent", null));
    Assertions.assertEquals("TRUE", decision(marketing, "granted").toUpperCase(),
        "The first decision is kept");
  }

  @Test
  @DisplayName("Without address nor agent the decision is stored without them")
  void store_without_origin() {
    Map<String, Boolean> decisions = new LinkedHashMap<>();
    decisions.put(marketing, null);

    consents.storePurposeDecisions("acme", "alice", decisions, " ", "");

    Assertions.assertEquals("FALSE", decision(marketing, "granted").toUpperCase(),
        "A decision without answer is a denial");
    Assertions.assertNull(decision(marketing, "ip_address"));
    Assertions.assertNull(decision(marketing, "user_agent"));
    Assertions.assertEquals(List.of(analytics), pending());
  }

  @Test
  @DisplayName("Unknown users or tenants and empty decisions store nothing")
  void unknown() {
    Assertions.assertEquals(List.of(), consents.pendingPurposes("acme", "bob"));
    Assertions.assertEquals(List.of(), consents.pendingPurposes("initech", "alice"));

    consents.storePurposeDecisions("acme", "bob", Map.of(marketing, true), null, null);
    consents.storePurposeDecisions("initech", "alice", Map.of(marketing, true), null, null);
    consents.storePurposeDecisions("acme", "alice", Map.of(), null, null);
    consents.storePurposeDecisions("acme", "alice", null, null, null);

    Assertions.assertEquals(0, store.db().count("identity_user_purpose_consent", null));
    Assertions.assertEquals(List.of(marketing, analytics), pending());
  }
}
